import { getKeyFromUrl } from '~/server/lib/storage';

// Minimal HTML helpers replacing BeautifulSoup usage in the post service. The content is
// generated by CKEditor (well-formed), so targeted regex gives identical results for the
// two operations the backend performs: collect resource keys from <img src>, and extract
// visible text for the search index after dropping script/style/pre blocks.

const IMG_TAG = /<img\b[^>]*>/gi;
const SRC_ATTR = /\bsrc\s*=\s*["']([^"']+)["']/i;

// Return the set of storage keys referenced by <img src="..."> that belong to our resource API.
export function extractImageKeys(html: string): Set<string> {
  const keys = new Set<string>();
  if (!html) return keys;
  for (const tag of html.match(IMG_TAG) ?? []) {
    const m = tag.match(SRC_ATTR);
    if (!m) continue;
    const key = getKeyFromUrl(m[1]);
    if (key) keys.add(key);
  }
  return keys;
}

// Strip script/style/pre, remove remaining tags, decode a few entities, collapse whitespace.
export function extractText(html: string): string {
  if (!html) return '';
  let s = html
    .replace(/<script\b[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[\s\S]*?<\/style>/gi, '')
    .replace(/<pre\b[\s\S]*?<\/pre>/gi, '');
  s = s.replace(/<[^>]+>/g, ' ');
  s = s
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
  return s.split(/\s+/).filter(Boolean).join(' ');
}
